fn rg_main(p: vec2<u32>) {
  let q = vec2<i32>(p);
  var n0_acc = vec4<f32>(0.0);
  var n0_w = 0.0;
  for (var n0_y = -2; n0_y <= 2; n0_y++) {
    for (var n0_x = -2; n0_x <= 2; n0_x++) {
      let n0_k = exp(-f32(n0_x * n0_x + n0_y * n0_y) / (2.0 * 1.5 * 1.5));
      n0_acc += n0_k * textureLoad(rg_in_src, clamp(q + vec2<i32>(n0_x, n0_y), vec2<i32>(0), vec2<i32>(textureDimensions(rg_in_src)) - vec2<i32>(1)), 0);
      n0_w += n0_k;
    }
  }
  let n0_value = n0_acc / n0_w;
  textureStore(rg_out_dst, p, n0_value);
}
